package me.danialisntcool.factionfriction.data;import java.util.*;import me.danialisntcool.factionfriction.faction.*;public class FactionManager {public Map<UUID,Faction> factions=new HashMap<>();public Map<Long,UUID> owners=new HashMap<>();public Map<Long,UUID> getChunkOwnerMap(){return owners;}public int dirty;public static FactionManager get(net.minecraft.server.MinecraftServer s){return s.manager;}public Map<UUID,Faction> getFactions(){return factions;}public Faction getFactionById(UUID id){return factions.get(id);}public Faction getFactionByPlayer(UUID id){return factions.values().stream().filter(f->f.members.containsKey(id)).findFirst().orElse(null);}public Faction getFactionByNameOrSlug(String name){return factions.values().stream().filter(f->f.name.equals(name)).findFirst().orElse(null);}public void setDirty(){dirty++;}}